namespace ks{class PanelToggleTask final{public:enum class Kind{SecondBit,FirstBit};enum class Stage{Hold,ReadMirror,MaskMirror,ReadInput,AdmitInput,Enable,WriteMirror,Dispatch,AwaitPublish,Restore,Finish,Complete};enum class Read{Mirror,Input};explicit PanelToggleTask(Kind k):kind_(k){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}uint8_t mirror()const{return mirror_;}uint8_t input()const{return input_;}bool awaiting()const{return stage_==Stage::AwaitPublish;}bool resumeChild(){if(!awaiting())return false;stage_=Stage::Restore;return true;}unsigned nextClocks()const{switch(stage_){case Stage::Hold:case Stage::Restore:return 11;case Stage::ReadMirror:case Stage::WriteMirror:return 12;case Stage::Dispatch:return 20;case Stage::Finish:return 17;case Stage::AwaitPublish:case Stage::Complete:return 0;default:return 3;}}
template<class Reader,class Writer>unsigned advanceBefore(unsigned available,Reader&&read,Writer&&write){unsigned used=0;while(auto cost=nextClocks()){if(cost>available-used)break;switch(stage_){case Stage::Hold:stage_=Stage::ReadMirror;break;case Stage::ReadMirror:mirror_=uint8_t(read(Read::Mirror));stage_=Stage::MaskMirror;break;case Stage::MaskMirror:mirror_&=kind_==Kind::SecondBit?1:2;stage_=Stage::ReadInput;break;case Stage::ReadInput:input_=uint8_t(read(Read::Input));stage_=Stage::AdmitInput;break;case Stage::AdmitInput:stage_=input_?Stage::Enable:Stage::WriteMirror;break;case Stage::Enable:mirror_|=kind_==Kind::SecondBit?2:1;stage_=Stage::WriteMirror;break;case Stage::WriteMirror:write(mirror_);stage_=Stage::Dispatch;break;case Stage::Dispatch:stage_=Stage::AwaitPublish;break;case Stage::Restore:stage_=Stage::Finish;break;case Stage::Finish:stage_=Stage::Complete;break;default:break;}used+=cost;}return used;}private:Kind kind_;Stage stage_=Stage::Hold;uint8_t mirror_=0,input_=0;};}
